insert into public.interactive_assignment_templates(slug,day,title,target_slugs,is_lab) values ('day-14-foundation-action-reaction',14,'Day 14 · Foundation lab: Newton’s third law',array['u1.third-law-pairs'],true);
insert into public.daily_lesson_templates(key,foundation_slug,review_slug,foundation_questions,review_questions,quiz) values ('unit-1-day-14','day-14-foundation-action-reaction','day-14-third-law',array['f14-predict','f14-pair','f14-readings','f14-revise','f14-impact','f14-exit'],array['r2-1a','r2-1b','r2-2a','r2-2b','r2-2c','r2-3a','r2-3b','r2-4a','r2-4b','r2-5a','r2-5b'],'{"title":"Day 14 · Quiz: Newton’s third law","instructions":"Work on your own. Name the object that feels each force.","questions":[{"kind":"choice","points":1,"prompt":"A hand pushes a wall right with 12 N. Which is its interaction partner?","options":["Wall on hand, 12 N left","Wall on hand, 12 N right","Earth on hand, 12 N down","Hand on wall, 12 N left"],"correct_index":0,"guide":"Swap the two objects and reverse direction.","demand":{"blooms":"Understand","dok":1,"evidence":"Identifies both receivers."}},{"kind":"choice","points":1,"prompt":"Two force sensors report signed readings on a common axis. Which comparison tests the third law?","options":["The largest reading on each graph at any time","Both readings at the same instant","Each sensor before the pull","The mass of each sensor"],"correct_index":1,"guide":"The two interaction forces occur at the same time.","demand":{"blooms":"Apply","dok":2,"evidence":"Selects simultaneous data."}},{"kind":"written","points":3,"prompt":"A table pushes a book up while Earth pulls the book down. Someone calls these a third-law pair. Check the claim and name each force’s actual partner.","guide":"Both act on the book. The partners are book on table and book on Earth, respectively.","demand":{"blooms":"Analyze","dok":2,"evidence":"Distinguishes balance from interaction pairs."}},{"kind":"written","points":3,"prompt":"A 2 kg cart and an 8 kg cart interact with 16 N of horizontal force on each. Ignore other horizontal forces. Compare directions and find both acceleration sizes.","guide":"The forces have opposite directions on different carts. Accelerations are 8 m/s² and 2 m/s² respectively, also opposite.","demand":{"blooms":"Apply","dok":2,"evidence":"Uses each mass with its own interaction force."}}]}'::jsonb);
